import java.util.Scanner;

public class Main {
    static int totalN, totalK, totalP;
    static int[][] memoArr;
    static int[] factArr, invFactArr;

    static int modExp(int base, int exp) {
        long res = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * cur) % totalP;
            }
            cur = (cur * cur) % totalP;
            exp >>= 1;
        }
        return (int) res;
    }

    static int getLowestBit(int x) {
        return x & (-x);
    }

    static void setupFactors() {
        factArr = new int[totalN + 1];
        invFactArr = new int[totalN + 1];
        factArr[0] = 1;
        for (int i = 1; i <= totalN; i++) {
            factArr[i] = (int) ((long) factArr[i - 1] * i % totalP);
        }
        invFactArr[totalN] = modExp(factArr[totalN], totalP - 2);
        for (int i = totalN; i >= 1; i--) {
            invFactArr[i - 1] = (int) ((long) invFactArr[i] * i % totalP);
        }
    }

    static int recursiveSolve(int current, int S) {
        if (memoArr[current][S] != -1) return memoArr[current][S];
        if (S == 0) {
            long res = factArr[totalN];
            for (int i = 1; i <= current; i++) {
                res = (res * (totalK - i + 1)) % totalP;
            }
            memoArr[current][S] = (int) res;
            return memoArr[current][S];
        }
        long sum = 0;
        int U = S - getLowestBit(S);
        for (int T = U; T != 0; T = (T - 1) & U) {
            long val = ((long) invFactArr[S - T] * recursiveSolve(current + 1, T)) % totalP;
            sum = (sum + val) % totalP;
        }
        long lastTerm = ((long) invFactArr[S] * recursiveSolve(current + 1, 0)) % totalP;
        sum = (sum + lastTerm) % totalP;
        memoArr[current][S] = (int) sum;
        return memoArr[current][S];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        totalN = sc.nextInt();
        totalK = sc.nextInt();
        totalP = sc.nextInt();

        int answer = 1;
        for (int i = 1; i <= totalN; i++) {
            answer = (int) ((long) answer * totalK % totalP);
        }

        if (totalN % 2 == 0) {
            setupFactors();
            memoArr = new int[26][250010];
            for (int i = 0; i < 26; i++) {
                for (int j = 0; j < 250010; j++) {
                    memoArr[i][j] = -1;
                }
            }
            answer = (answer - recursiveSolve(0, totalN) + totalP) % totalP;
        }

        System.out.println(answer);
        sc.close();
    }
}
